package com.finstack.fraud;
import com.finstack.transaction.Transaction; import com.finstack.user.User; import jakarta.persistence.*; import java.time.*; import java.util.*;
@Entity @Table(name="transaction_fraud_assessments") public class FraudAssessment { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="event_id",nullable=false,unique=true) private UUID eventId; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="transaction_id",nullable=false) private Transaction transaction; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="user_id",nullable=false) private User user; private int riskScore; @Enumerated(EnumType.STRING) private RiskLevel riskLevel; private boolean suspicious; @Column(nullable=false,length=2000) private String reasons; @Column(name="evaluated_at",nullable=false) private OffsetDateTime evaluatedAt; @Column(name="rules_version",nullable=false) private String rulesVersion; protected FraudAssessment(){} public FraudAssessment(UUID e,Transaction t,User u,int score,RiskLevel level,boolean suspicious,String reasons){eventId=e;transaction=t;user=u;riskScore=score;riskLevel=level;this.suspicious=suspicious;this.reasons=reasons;evaluatedAt=OffsetDateTime.now(ZoneOffset.UTC);rulesVersion="rules-v1";} public UUID getId(){return id;} public UUID getEventId(){return eventId;} public Transaction getTransaction(){return transaction;} public User getUser(){return user;} public int getRiskScore(){return riskScore;} public RiskLevel getRiskLevel(){return riskLevel;} public boolean isSuspicious(){return suspicious;} public String getReasons(){return reasons;} public OffsetDateTime getEvaluatedAt(){return evaluatedAt;} }
